package edu.casestudy.merkle.core;
import java.util.*;
public final class MerkleTree { public record Leaf(UUID id,long position,String payload){} private final List<List<MerkleNode>> levels; private final List<Leaf> leaves;
 public MerkleTree(List<Leaf> input){leaves=input.stream().sorted(Comparator.comparingLong(Leaf::position).thenComparing(x->x.id().toString())).toList();var bottom=new ArrayList<MerkleNode>();for(var x:leaves) bottom.add(new MerkleNode(HashUtils.hex(HashUtils.leaf(RecordCanonicalizer.canonical(x.id(),x.position(),x.payload()))),x.id().toString(),null,null));levels=new ArrayList<>();levels.add(bottom);var cur=bottom;while(cur.size()>1){var n=new ArrayList<MerkleNode>();for(int i=0;i<cur.size();i+=2){var l=cur.get(i);var r=i+1<cur.size()?cur.get(i+1):l;n.add(new MerkleNode(HashUtils.hex(HashUtils.parent(HashUtils.unhex(l.hash()),HashUtils.unhex(r.hash()))),null,l,r));}levels.add(n);cur=n;}}
 public String root(){return leaves.isEmpty()?HashUtils.hex(HashUtils.empty()):levels.get(levels.size()-1).get(0).hash();} public MerkleNode structure(){return leaves.isEmpty()?null:levels.get(levels.size()-1).get(0);} public MerkleProof proof(UUID id){int p=-1;for(int i=0;i<leaves.size();i++)if(leaves.get(i).id().equals(id)){p=i;break;}if(p<0)throw new IllegalArgumentException("Record not in tree");var steps=new ArrayList<MerkleProof.Step>();for(int l=0;l<levels.size()-1;l++){var level=levels.get(l);int peer=p%2==0?p+1:p-1;if(peer>=level.size())peer=p;steps.add(new MerkleProof.Step(level.get(peer).hash(),p%2==1));p/=2;}return new MerkleProof(levels.get(0).get(index(id)).hash(),steps);}private int index(UUID id){for(int i=0;i<leaves.size();i++)if(leaves.get(i).id().equals(id))return i;throw new IllegalArgumentException();} }
